// The tutor's prompt (docs/08-ai-tutor.qmd, "What the AI is told"). One builder for the ai-chat Edge Function
// (instructor-key mode) and the frame (student-key mode), so both say the same thing. Built in a fixed order so
// the stable parts (system prompt, instructor instructions, page context) cache across students on a page.

export type TutorAction = 'confused' | 'simpler' | 'example' | 'quiz' | 'ask' | 'summarize' | 'remember' | 'explain-code' | 'hint'

export interface TutorContext {
  bookTitle: string
  courseLabel?: string                 // "AI Assisted Development 331"
  instructorInstructions?: string      // the section's ai.instructions
  pageTitle: string
  headingPath: string[]
  sectionText: string                  // the current section's text, answers removed
  before?: string                      // a little of the previous section
  after?: string                       // a little of the next section
  coverage?: string                    // "Covered in class on Oct 21 (Class 12). The next section was skipped."
}

export const ACTION_LABEL: Record<TutorAction, string> = {
  confused: "I don't understand this",
  simpler: 'Explain it more simply',
  example: 'Show me an example',
  quiz: 'Quiz me on this',
  ask: 'Ask a specific question',
  summarize: 'Summarize this section',
  remember: 'What should I remember from this section?',
  'explain-code': 'Explain this code line by line',
  hint: 'Give me a hint',
}

const MAX_SECTION = 16000   // characters, about 4,000 tokens
const MAX_SIDE = 1500

export function systemPrompt(ctx: TutorContext): string {
  return [
    `You are a patient tutor for the online book "${ctx.bookTitle}"${ctx.courseLabel ? `, used in the course ${ctx.courseLabel}` : ''}.`,
    'Explain at the level of a student who is reading this book for a course. Prefer short answers, concrete examples, and questions that lead the student to the idea over handing the idea over. When the student is working on a practice question, give hints, not the answer, unless the instructor\'s instructions below allow solutions.',
    'Stay with the book: use its terms and its examples. If a question is outside the book, say so briefly and answer anyway if it helps the student understand the book.',
    'Use Markdown sparingly: short paragraphs, code in fenced blocks when it is code, no headings.',
    ctx.instructorInstructions ? `\nInstructions from the instructor of this section:\n${ctx.instructorInstructions.trim()}` : '',
  ].filter(Boolean).join('\n')
}

export function pageContextBlock(ctx: TutorContext): string {
  const parts = [`Page: ${ctx.pageTitle}`, `Section: ${ctx.headingPath.join(' › ') || '(top of page)'}`]
  if (ctx.before) parts.push(`\nEnd of the previous section:\n${ctx.before.slice(-MAX_SIDE)}`)
  parts.push(`\nThe current section:\n${ctx.sectionText.slice(0, MAX_SECTION)}`)
  if (ctx.after) parts.push(`\nStart of the next section:\n${ctx.after.slice(0, MAX_SIDE)}`)
  if (ctx.coverage) parts.push(`\nWhat the class has covered here: ${ctx.coverage}`)
  return parts.join('\n')
}

/** The first user turn: the passage and the action. */
export function firstTurn(action: TutorAction, passage: string | null, question?: string): string {
  const quoted = passage ? `The student selected this passage:\n«${passage.trim().slice(0, 4000)}»\n\n` : ''
  switch (action) {
    case 'confused': return `${quoted}The student says: I don't understand this. Find the likely sticking point and explain it, then check with one short question.`
    case 'simpler': return `${quoted}Explain this more simply, in plain words, with one everyday analogy if it helps.`
    case 'example': return `${quoted}Show one concrete worked example of this idea, different from the book's.`
    case 'quiz': return `${quoted}Quiz the student on this: ask one question at a time, wait for the answer, then say what was right and what was missing.`
    case 'summarize': return `${quoted}Summarize this section in a few sentences a student could study from.`
    case 'remember': return `${quoted}What are the two or three things to remember from this section, and why do they matter?`
    case 'explain-code': return `${quoted}Explain this code line by line, briefly, then what it does as a whole.`
    case 'hint': return `${quoted}The student is working on this practice question. Give a hint that moves them forward without giving the answer.`
    case 'ask':
    default: return `${quoted}The student asks: ${(question || '').trim() || '(no question given; ask what they want to know)'}`
  }
}
