import { useState } from 'preact/hooks'
import { store, type State } from '../store.ts'

const DEV = location.hash.includes('dev') || location.hostname === 'localhost'

export function SignIn({ s }: { s: State }) {
  const [email, setEmail] = useState('')
  const [pw, setPw] = useState('')
  if (s.session) {
    return (
      <div class="card">
        <div>Signed in as <strong>{s.profile?.display_name || s.session.user.email}</strong>{s.profile?.handle ? ` (@${s.profile.handle})` : ''}</div>
        <button class="link" onClick={() => store.signOut()}>Sign out</button>
      </div>
    )
  }
  return (
    <div class="card">
      <p class="muted">Coverage shows without signing in. Sign in to take notes, comment, or mark coverage.</p>
      <button class="primary" disabled={s.busy} onClick={() => store.signIn()}>Sign in with GitHub</button>
      {DEV && (
        <form class="dev" onSubmit={(e) => { e.preventDefault(); store.devSignIn(email, pw) }}>
          <div class="muted small">Test account (dev only)</div>
          <input type="email" placeholder="email" value={email} onInput={(e) => setEmail((e.target as HTMLInputElement).value)} />
          <input type="password" placeholder="password" value={pw} onInput={(e) => setPw((e.target as HTMLInputElement).value)} />
          <button type="submit" disabled={s.busy}>Sign in</button>
        </form>
      )}
    </div>
  )
}
