// The postMessage protocol between the page script (in the book's page) and the frame (on the platform origin).
// A fixed list of messages, each checked by the receiver (docs/03-architecture.qmd, "bridge.ts").
import type { Anchor, CoverageStatus, MarkKind, MarkRow } from './types.ts'

export const PROTOCOL = 1

/** What the frame tells the page script about the current state. Nothing private is in here. */
export interface OverlayState {
  protocol: number
  disabled: boolean                    // the package's kill switch
  packageTitle: string
  packageSlug: string
  originOk: boolean                    // the page's origin is registered for the package (or localhost for a maintainer)
  signedIn: boolean
  userId: string | null
  displayName: string | null
  canTeach: boolean                    // staff of at least one section that uses this package
  teach: boolean                       // Teach mode on
  showNotes: boolean                   // draw private notes (instructor's own) on the page
  section: { id: string; slug: string; label: string; course: string } | null
  sections: Array<{ id: string; slug: string; label: string; course: string }>   // sections the viewer may pick
  build: string | null
  page: string                         // canonical page id, computed by the frame from the package's site URL
  versionSuffix?: string               // the package's page_version_suffix, for sidebar dots
  ai: { mode: 'off' | 'instructor' | 'student' | 'either'; tutor: boolean }   // the section's mode; tutor false = author switched it off
  hideFromTutor: string[]              // selectors left out of the tutor's context (answers)
}

export type PageToFrame =
  | { type: 'yrS4:hello'; protocol: number; version: string; package: string; page: string; path: string; href: string; title: string; section: string | null }
  | { type: 'yrS4:mark:create'; kind: MarkKind; anchor: Anchor; status?: CoverageStatus; quoteText?: string; data?: Record<string, unknown> }
  | { type: 'yrS4:mark:open'; id: string }
  | { type: 'yrS4:mark:delete'; id: string }
  | { type: 'yrS4:panel:toggled'; open: boolean }
  | { type: 'yrS4:orphans'; ids: string[] }
  | { type: 'yrS4:ask'; anchor: Anchor; action: 'ask' | 'summarize' | 'explain-code'; passage: string | null; context: { pageTitle: string; headingPath: string[]; sectionText: string; before?: string; after?: string } }
  | { type: 'yrS4:reattach'; items: Array<{ id: string; anchor_current: Anchor }> }   // fuzzy matches found on this view (unconfirmed)
  | { type: 'yrS4:error'; message: string; stack?: string }

export type FrameToPage =
  | { type: 'yrS4:state'; state: OverlayState }
  | { type: 'yrS4:marks'; marks: MarkRow[] }
  | { type: 'yrS4:panel'; open: boolean }
  | { type: 'yrS4:goto'; id: string }
  | { type: 'yrS4:toast'; text: string; undo?: string }
  | { type: 'yrS4:pages'; coverage: Record<string, 'full' | 'partial'> }   // per canonical page id, for sidebar dots
  | { type: 'yrS4:activity'; items: Array<{ anchor: Anchor; emoji: string; label: string; n: number }> }   // staff: reaction counts on this page
  | { type: 'yrS4:kill' }

export function isPageToFrame(x: unknown): x is PageToFrame {
  return !!x && typeof x === 'object' && typeof (x as { type?: unknown }).type === 'string' && (x as { type: string }).type.startsWith('yrS4:')
}
export const isFrameToPage = isPageToFrame as unknown as (x: unknown) => x is FrameToPage
