// The frame's state and actions. The UI (ui/App.tsx) renders it; the page script hears about it through
// postMessage (shared/protocol.ts). Private text never leaves this frame.
import type { Session } from '@supabase/supabase-js'
import type { Anchor, CoverageStatus, MarkKind, MarkRow, PackageRow, SectionRow } from '../../shared/types.ts'
import { PROTOCOL, isPageToFrame, type FrameToPage, type OverlayState, type PageToFrame } from '../../shared/protocol.ts'
import * as api from './api.ts'
import { originAllowed } from './scope.ts'
import { canonicalPageId, pagePathFor } from '../../shared/pageid.ts'
import { signInWithGitHub } from './session.ts'
import { askServer, askWithStudentKey, getStudentKey, TutorError, type TutorRequest } from './features/tutor.ts'
import type { TutorAction, TutorContext } from '../../supabase/functions/_shared/tutor-prompt.ts'

declare const __YRS4_VERSION__: string
export const VERSION = typeof __YRS4_VERSION__ === 'string' ? __YRS4_VERSION__ : 'dev'

export interface Hello { package: string; page: string; path: string; href: string; title: string; section: string | null; origin: string }
export interface TutorState {
  request: TutorRequest
  messages: Array<{ role: 'user' | 'assistant'; content: string }>
  streaming: boolean
  error: string | null
  offerStudentKey?: boolean
  deep: boolean
  cost?: number
  model?: string
  abort?: AbortController
}

export interface Pending { kind: MarkKind; anchor: Anchor; status?: CoverageStatus; quoteText?: string; editing?: MarkRow }
export type View = 'page' | 'notes' | 'messages' | 'settings'

export interface State {
  hello: Hello | null
  pkg: PackageRow | null
  build: api.BuildRow | null
  session: Session | null
  profile: api.Profile | null
  sections: SectionRow[]
  staffIds: string[]
  enrolledIds: string[]               // sections the viewer joined
  joinCodes: Record<string, string>   // staff only: by section id
  replies: Record<string, api.Reply[]> // by mark id
  section: SectionRow | null          // the section whose coverage the reader sees
  teach: boolean
  teachSections: string[]             // section ids ticked in the Teach bar
  meetingDate: string                 // YYYY-MM-DD
  showNotes: boolean
  showActivity: boolean
  marks: MarkRow[]
  orphans: string[]
  reattach: Record<string, Anchor>     // fuzzy matches the page found, awaiting confirmation
  pending: Pending | null
  tutor: TutorState | null
  view: View
  focusMark: string | null
  error: string | null
  busy: boolean
  originOk: boolean
  disabled: boolean
  embedded: boolean
  loading: boolean
}

export const today = () => new Date().toLocaleDateString('en-CA')
const sectionLabel = (s: SectionRow) => ({ id: s.id, slug: s.slug, label: s.label, course: s.course?.code || '' })

export class Store {
  state: State = {
    hello: null, pkg: null, build: null, session: null, profile: null, sections: [], staffIds: [], enrolledIds: [], joinCodes: {}, replies: {}, section: null,
    teach: false, teachSections: [], meetingDate: today(), showNotes: false, showActivity: false, marks: [], orphans: [], reattach: {}, pending: null, tutor: null,
    view: 'page', focusMark: null, error: null, busy: false, originOk: false, disabled: false,
    embedded: window.parent !== window, loading: true,
  }
  private listeners = new Set<() => void>()
  private pageOrigin: string | null = null
  private pageWindow: Window | null = null

  subscribe(fn: () => void) {
    this.listeners.add(fn)
    return () => this.listeners.delete(fn)
  }
  private set(patch: Partial<State>) {
    this.state = { ...this.state, ...patch }
    for (const l of this.listeners) l()
  }

  // --- startup ----------------------------------------------------------------------------------------------------
  async start() {
    window.addEventListener('message', (e) => this.onMessage(e))
    const session = await api.getSession()
    this.set({ session })
    api.onAuthChange((s) => {
      const was = !!this.state.session
      this.set({ session: s, ...(s ? {} : { profile: null }) })
      if (!!s !== was) {
        if (s) void this.loadProfile().then(() => this.reloadForUser())
        else void this.reloadForUser()
      }
    })
    if (session) await this.loadProfile()
    if (!this.state.embedded) {
      // Opened directly (not inside a book): show the sign-in and settings only.
      this.set({ loading: false })
    }
  }

  private async loadProfile() {
    try {
      this.set({ profile: await api.myProfile() })
    } catch (e) {
      this.fail(e)
    }
  }

  private onMessage(e: MessageEvent) {
    if (!isPageToFrame(e.data)) return
    if (this.pageOrigin && e.origin !== this.pageOrigin) return
    if (e.source !== window.parent) return
    const m = e.data as PageToFrame
    if (m.type === 'yrS4:hello') {
      this.pageOrigin = e.origin
      this.pageWindow = e.source as Window
      void this.hello({ package: m.package, page: m.page, path: m.path, href: m.href, title: m.title, section: m.section, origin: e.origin })
      return
    }
    if (!this.pageOrigin) return
    switch (m.type) {
      case 'yrS4:mark:create': return void this.create(m.kind, m.anchor, m.status, m.quoteText, m.data)
      case 'yrS4:mark:open': return this.set({ focusMark: m.id, view: 'page' })
      case 'yrS4:mark:delete': return void this.remove(m.id)
      case 'yrS4:orphans': return this.set({ orphans: m.ids })
      case 'yrS4:ask': return this.openTutor({ package: this.state.pkg!.slug, page: this.state.hello!.page, section: this.state.section?.id || null, anchor: m.anchor, action: m.action, passage: m.passage, context: m.context })
      case 'yrS4:reattach': return this.set({ reattach: Object.fromEntries(m.items.map((x) => [x.id, x.anchor_current])) })
      case 'yrS4:error': return void api.reportError({ package: this.state.hello?.package, page: this.state.hello?.page, origin: this.pageOrigin || undefined, message: m.message, stack: m.stack, version: VERSION })
      case 'yrS4:panel:toggled': return
    }
  }

  send(m: FrameToPage) {
    if (this.pageWindow && this.pageOrigin) this.pageWindow.postMessage(m, this.pageOrigin)
  }

  private async hello(h: Hello) {
    this.set({ hello: h, loading: true, error: null })
    try {
      const pkg = await api.packageBySlug(h.package)
      if (!pkg) {
        this.set({ loading: false, error: `This page says it belongs to the package "${h.package}", which the platform doesn't know.` })
        return
      }
      if (pkg.disabled) {
        this.set({ pkg, disabled: true, loading: false })
        this.send({ type: 'yrS4:kill' })
        return
      }
      const originOk = originAllowed(pkg, h.origin)
      // The canonical page id: the path relative to the book's site, without extension and version suffix.
      const suffix = (pkg.manifest as { overlay?: { page_version_suffix?: string } })?.overlay?.page_version_suffix
      let page = pkg.site_url ? canonicalPageId(pagePathFor(h.href, pkg.site_url), suffix) : h.page
      const underSite = !!pkg.site_url && new URL(h.href).href.startsWith(new URL(pkg.site_url).href)
      if (!underSite) {
        // a preview (localhost) or another copy: ask the build record which page this path is
        try {
          const resolved = await api.pageForPath(pkg.id, new URL(h.href).pathname)
          if (resolved) page = resolved
        } catch { /* keep the computed id */ }
      }
      this.set({ pkg, originOk, hello: { ...h, page } })
      this.restorePrefs(pkg.id)
      await this.reloadForUser()
    } catch (e) {
      this.fail(e)
    } finally {
      this.set({ loading: false })
    }
  }

  /** Everything that depends on who is signed in. */
  private async reloadForUser() {
    const { pkg, hello } = this.state
    if (!pkg || !hello) return
    try {
      if (this.state.session && !this.state.profile) await this.loadProfile()
      if (!this.state.session) this.set({ profile: null })
      const [sections, staffIds, build, enrolledIds] = await Promise.all([api.sectionsForPackage(pkg.id), api.myStaffSectionIds(), api.latestBuild(pkg.id), api.myEnrollments()])
      let section = hello.section ? sections.find((s) => s.slug === hello.section) || null : null
      if (!section && this.state.section) section = sections.find((s) => s.id === this.state.section!.id) || null
      const canTeach = staffIds.some((id) => sections.some((s) => s.id === id))
      const teachSections = this.state.teachSections.filter((id) => staffIds.includes(id))
      if (canTeach && !teachSections.length) teachSections.push(...sections.filter((s) => staffIds.includes(s.id)).map((s) => s.id))
      // a student who joined exactly one of these sections sees it by default
      if (!section && !canTeach) {
        const mine = sections.filter((x) => enrolledIds.includes(x.id))
        if (mine.length === 1) section = mine[0]
      }
      this.set({ sections, staffIds, enrolledIds, build, section, teachSections, teach: canTeach && this.state.teach })
      await this.loadMarks()
      void this.loadJoinCodes()
    } catch (e) {
      this.fail(e)
    }
    this.pushState()
  }

  async loadMarks() {
    const { pkg, hello } = this.state
    if (!pkg || !hello) return
    const marks = await api.pageMarks(pkg.id, hello.page)
    this.set({ marks })
    this.pushMarks()
    this.cacheMarks(marks)
    void this.loadPageCoverage()
    void this.loadReplies(marks.filter((m) => m.kind === 'message' || m.kind === 'author_note').map((m) => m.id))
  }

  async loadReplies(ids: string[]) {
    if (!ids.length || !this.state.session) return
    try {
      const rows = await api.replies(ids)
      const replies = { ...this.state.replies }
      for (const id of ids) replies[id] = []
      for (const r of rows) replies[r.mark_id] = [...(replies[r.mark_id] || []), r]
      this.set({ replies })
    } catch (e) {
      console.warn('[yrS4 frame] replies', e)
    }
  }

  /** Which pages of the book have coverage for the viewer's section(s): drives the sidebar dots. */
  async loadPageCoverage() {
    const { pkg } = this.state
    if (!pkg) return
    try {
      const ids = new Set(this.state.teach ? this.state.teachSections : this.state.section ? [this.state.section.id] : [])
      if (!ids.size) return this.send({ type: 'yrS4:pages', coverage: {} })
      const all = await api.pageMarks(pkg.id, null, ['coverage'])
      const coverage: Record<string, 'full' | 'partial'> = {}
      for (const m of all) {
        if (!m.page || !m.sections.some((x) => ids.has(x.section_id))) continue
        if (m.data.status !== 'covered') continue
        const full = (m.anchor_current || m.anchor)?.scope === 'page'
        coverage[m.page] = full || coverage[m.page] === 'full' ? 'full' : 'partial'
      }
      this.send({ type: 'yrS4:pages', coverage })
    } catch (e) {
      console.warn('[yrS4 frame] page coverage', e)
    }
  }

  async confirmReattach(m: MarkRow) {
    const a = this.state.reattach[m.id]
    if (!a) return
    try {
      await api.updateMark(m.id, { anchor_current: a })
      const { [m.id]: _, ...rest } = this.state.reattach
      this.set({ marks: this.state.marks.map((x) => (x.id === m.id ? { ...x, anchor_current: a } : x)), reattach: rest })
      this.pushMarks()
      this.toast('Re-attached')
    } catch (e) {
      this.fail(e)
    }
  }

  async joinSection(code: string) {
    this.set({ busy: true, error: null })
    try {
      await api.joinSection(code.trim())
      this.toast('Joined')
      await this.reloadForUser()
    } catch (e) {
      this.fail(e)
    } finally {
      this.set({ busy: false })
    }
  }
  async setJoinCode(sectionId: string, code: string | null) {
    try {
      await api.setJoinCode(sectionId, code)
      const joinCodes = { ...this.state.joinCodes }
      if (code) joinCodes[sectionId] = code
      else delete joinCodes[sectionId]
      this.set({ joinCodes })
    } catch (e) {
      this.fail(e)
    }
  }
  async loadJoinCodes() {
    const mine = this.state.staffIds.filter((id) => this.state.sections.some((x) => x.id === id))
    if (!mine.length) return
    try {
      this.set({ joinCodes: await api.joinCodes(mine) })
    } catch (e) {
      console.warn('[yrS4 frame] join codes', e)
    }
  }
  async reply(m: MarkRow, body: string) {
    if (!body.trim()) return
    try {
      const r = await api.reply(m.id, body.trim())
      r.author = { display_name: this.state.profile?.display_name || 'me' }
      this.set({ replies: { ...this.state.replies, [m.id]: [...(this.state.replies[m.id] || []), r] } })
    } catch (e) {
      this.fail(e)
    }
  }
  /** An "error in the book" message becomes a private author note for the next packet (docs/09-student-features.qmd). */
  async makeAuthorNote(m: MarkRow) {
    const { pkg, build } = this.state
    if (!pkg || !m.anchor) return
    try {
      const body = `From a student message (${(m.data.topic as string) || 'message'}):\n\n${m.body || ''}`
      await api.createMark({ kind: 'author_note', package_id: pkg.id, page: m.page, anchor: m.anchor, body, data: { category: 'fix', priority: 2, from_message: m.id }, build_id: build?.id || null }, [])
      this.toast('Author note made')
      await this.loadMarks()
    } catch (e) {
      this.fail(e)
    }
  }

  // --- the tutor ----------------------------------------------------------------------------------------------------
  openTutor(request: TutorRequest) {
    if (!this.state.session) {
      this.set({ view: 'page', error: 'Sign in to use the tutor.' })
      return
    }
    this.set({ tutor: { request, messages: [], streaming: false, error: null, deep: false }, view: 'page', pending: null })
  }
  closeTutor() {
    this.state.tutor?.abort?.abort()
    this.set({ tutor: null })
  }
  askInstructorInstead() {
    const t = this.state.tutor
    if (!t) return
    this.set({ tutor: null, pending: { kind: 'message', anchor: t.request.anchor as Anchor, quoteText: t.request.passage || undefined } })
  }
  async askTutorDeeper() {
    const t = this.state.tutor
    if (!t || !t.messages.length) return
    const first = t.messages[0]
    this.set({ tutor: { ...t, messages: [], deep: true, request: { ...t.request, conversation_id: null } } })
    await this.askTutor(t.request.action, first.role === 'user' ? first.content : undefined)
  }
  async askTutor(action: TutorAction, question?: string) {
    const t = this.state.tutor
    if (!t || t.streaming) return
    const mode = ((this.state.section?.ai as { mode?: string })?.mode || 'off')
    const label = question?.trim() || action
    const history = t.messages
    const abort = new AbortController()
    const messages = [...history, { role: 'user' as const, content: label }, { role: 'assistant' as const, content: '' }]
    this.set({ tutor: { ...t, messages, streaming: true, error: null, abort, request: { ...t.request, action: history.length ? t.request.action : action } } })
    const onDelta = (text: string) => {
      const cur = this.state.tutor
      if (!cur) return
      const ms = cur.messages.slice()
      ms[ms.length - 1] = { role: 'assistant', content: ms[ms.length - 1].content + text }
      this.set({ tutor: { ...cur, messages: ms } })
    }
    const req: TutorRequest = { ...t.request, action: history.length ? t.request.action : action, question, deep: t.deep, conversation_id: t.request.conversation_id || null }
    try {
      let result
      const useStudentKey = mode === 'student' || (mode === 'either' && t.offerStudentKey && getStudentKey())
      if (useStudentKey) {
        const ctx: TutorContext = { bookTitle: this.state.pkg?.title || '', courseLabel: this.state.section ? `${this.state.section.course?.code || ''} ${this.state.section.label}` : undefined,
          instructorInstructions: (this.state.section?.ai as { instructions?: string })?.instructions, ...t.request.context }
        result = await askWithStudentKey(req, ctx, history.map((m) => ({ role: m.role, content: m.content })), onDelta, abort.signal)
      } else {
        result = await askServer(req, onDelta, abort.signal)
      }
      const cur = this.state.tutor
      if (cur) this.set({ tutor: { ...cur, streaming: false, cost: (cur.cost || 0) + (result.cost_usd || 0), model: result.model, request: { ...cur.request, conversation_id: result.conversation_id } } })
    } catch (e) {
      const cur = this.state.tutor
      if (!cur) return
      const te = e instanceof TutorError ? e : null
      this.set({ tutor: { ...cur, streaming: false, error: e instanceof Error ? e.message : String(e), offerStudentKey: te?.offerStudentKey, messages: cur.messages.slice(0, -1) } })
    }
  }

  async setSectionAi(sectionId: string, ai: Record<string, unknown>) {
    try {
      await api.setSectionAi(sectionId, ai)
      this.set({ sections: this.state.sections.map((x) => (x.id === sectionId ? { ...x, ai } : x)), section: this.state.section?.id === sectionId ? { ...this.state.section, ai } : this.state.section })
      this.pushState()
    } catch (e) {
      this.fail(e)
    }
  }

  noteOnPage() {
    const { pkg, hello } = this.state
    if (!pkg || !hello) return
    const anchor: Anchor = { package: pkg.slug, page: hello.page, scope: 'page', section: { id: '', headings: [hello.title] }, build: this.state.build?.id || 'local' }
    this.set({ pending: { kind: 'author_note', anchor, quoteText: 'whole page' }, view: 'page' })
  }

  // --- what the page sees --------------------------------------------------------------------------------------
  private pushState() {
    const s = this.state
    const canTeach = s.staffIds.some((id) => s.sections.some((x) => x.id === id))
    const st: OverlayState = {
      protocol: PROTOCOL,
      disabled: s.disabled,
      packageTitle: s.pkg?.title || '',
      packageSlug: s.pkg?.slug || '',
      originOk: s.originOk,
      signedIn: !!s.session,
      userId: s.session?.user.id || null,
      displayName: s.profile?.display_name || null,
      canTeach,
      teach: s.teach,
      showNotes: s.showNotes,
      section: s.section ? sectionLabel(s.section) : null,
      sections: s.sections.map(sectionLabel),
      build: s.build?.id || null,
      page: s.hello?.page || '',
      versionSuffix: (s.pkg?.manifest as { overlay?: { page_version_suffix?: string } })?.overlay?.page_version_suffix,
      ai: { mode: ((s.section?.ai as { mode?: string })?.mode as 'off' | 'instructor' | 'student' | 'either') || 'off', tutor: (s.pkg?.manifest as { ai?: { tutor?: boolean } })?.ai?.tutor !== false },
      hideFromTutor: (s.pkg?.manifest as { overlay?: { hide_from_tutor?: string[] } })?.overlay?.hide_from_tutor || [],
    }
    this.send({ type: 'yrS4:state', state: st })
    this.pushMarks()
  }

  /** The marks the page should draw: this section's coverage and comments (or the Teach sections'), plus own notes. */
  visibleMarks(): MarkRow[] {
    const s = this.state
    const uid = s.session?.user.id
    const sectionIds = new Set(s.teach ? s.teachSections : s.section ? [s.section.id] : [])
    return s.marks.filter((m) => {
      if (m.kind === 'coverage' || m.kind === 'comment') return m.sections.some((x) => sectionIds.has(x.section_id))
      if (m.kind === 'author_note' || m.kind === 'student_note') return m.author_id === uid
      if (m.kind === 'message') return m.author_id === uid || m.sections.some((x) => s.staffIds.includes(x.section_id))
      if (m.kind === 'reaction') return m.author_id === uid
      return false
    })
  }
  private pushMarks() {
    this.send({ type: 'yrS4:marks', marks: this.visibleMarks() })
  }

  // --- preferences (this frame's storage: per book origin, because it's partitioned) ---------------------------------
  private prefKey(pkgId: string) {
    return `yrS4-prefs-${pkgId}`
  }
  private restorePrefs(pkgId: string) {
    try {
      const p = JSON.parse(localStorage.getItem(this.prefKey(pkgId)) || '{}')
      this.set({ teach: !!p.teach, teachSections: p.teachSections || [], showNotes: !!p.showNotes })
    } catch { /* ignore */ }
  }
  private savePrefs() {
    const { pkg, teach, teachSections, showNotes } = this.state
    if (!pkg) return
    try {
      localStorage.setItem(this.prefKey(pkg.id), JSON.stringify({ teach, teachSections, showNotes }))
    } catch { /* ignore */ }
  }
  private cacheMarks(marks: MarkRow[]) {
    const { pkg, hello } = this.state
    if (!pkg || !hello) return
    try {
      localStorage.setItem(`yrS4-cache-${pkg.id}-${hello.page}`, JSON.stringify({ at: Date.now(), marks }))
    } catch { /* ignore */ }
  }

  // --- actions ------------------------------------------------------------------------------------------------------
  setView(view: View) {
    this.set({ view, focusMark: null })
  }
  setTeach(on: boolean) {
    this.set({ teach: on })
    this.savePrefs()
    this.pushState()
    void this.loadPageCoverage()
  }
  async setShowActivity(on: boolean) {
    this.set({ showActivity: on })
    await this.loadActivity()
  }
  async loadActivity() {
    const { pkg, hello, showActivity, teachSections } = this.state
    if (!pkg || !hello) return
    if (!showActivity || !teachSections.length) return this.send({ type: 'yrS4:activity', items: [] })
    try {
      const all = await Promise.all(teachSections.map((s) => api.reactionCounts(s, pkg.id, hello.page)))
      const items = all.flat().map((x) => ({ anchor: x.anchor as Anchor, emoji: x.emoji, label: x.label, n: Number(x.n) }))
      this.send({ type: 'yrS4:activity', items })
    } catch (e) {
      console.warn('[yrS4 frame] activity', e)
    }
  }
  setShowNotes(on: boolean) {
    this.set({ showNotes: on })
    this.savePrefs()
    this.pushState()
  }
  toggleTeachSection(id: string) {
    const cur = new Set(this.state.teachSections)
    cur.has(id) ? cur.delete(id) : cur.add(id)
    this.set({ teachSections: [...cur] })
    this.savePrefs()
    this.pushMarks()
    void this.loadPageCoverage()
  }
  setMeetingDate(d: string) {
    this.set({ meetingDate: d })
  }
  chooseSection(slug: string | null) {
    const section = slug ? this.state.sections.find((s) => s.slug === slug) || null : null
    this.set({ section })
    this.pushState()
    void this.loadPageCoverage()
  }
  openPanel(open = true) {
    this.send({ type: 'yrS4:panel', open })
  }
  goto(id: string) {
    this.send({ type: 'yrS4:goto', id })
  }
  toast(text: string) {
    this.send({ type: 'yrS4:toast', text })
  }
  fail(e: unknown) {
    const msg = e instanceof Error ? e.message : String(e)
    console.error('[yrS4 frame]', e)
    this.set({ error: msg, busy: false })
  }
  clearError() {
    this.set({ error: null })
  }

  async signIn() {
    this.set({ busy: true, error: null })
    try {
      await signInWithGitHub()
    } catch (e) {
      this.fail(e)
    } finally {
      this.set({ busy: false })
    }
  }
  async devSignIn(email: string, password: string) {
    this.set({ busy: true, error: null })
    try {
      await api.devSignIn(email, password)
    } catch (e) {
      this.fail(e)
    } finally {
      this.set({ busy: false })
    }
  }
  async signOut() {
    await api.signOut()
    this.set({ teach: false, profile: null })
    this.savePrefs()
  }

  /** A toolbar button was pressed on the page. Coverage saves at once when the Teach bar is set; the rest opens an editor. */
  private async create(kind: MarkKind, anchor: Anchor, status?: CoverageStatus, quoteText?: string, data?: Record<string, unknown>) {
    if (!this.state.session) {
      this.set({ view: 'page', error: 'Sign in to save marks.' })
      this.openPanel(true)
      return
    }
    if (kind === 'student_note' && data?.highlight) {
      await this.saveText({ kind, anchor, quoteText }, '', { highlight: true })
      return
    }
    if (kind === 'reaction') {
      // a repeat press on the same passage and emoji removes the reaction
      const same = this.state.marks.find((m) => m.kind === 'reaction' && m.author_id === this.state.session!.user.id && m.data.emoji === data?.emoji && JSON.stringify(m.anchor?.quote) === JSON.stringify(anchor.quote) && m.anchor?.section?.id === anchor.section?.id)
      if (same) {
        await this.remove(same.id)
        return
      }
      await this.saveText({ kind, anchor, quoteText }, '', data || {})
      return
    }
    if (kind === 'coverage') {
      if (!this.state.teachSections.length) {
        this.set({ pending: { kind, anchor, status, quoteText }, view: 'page' })
        this.openPanel(true)
        return
      }
      await this.saveCoverage(anchor, status || 'covered')
      return
    }
    this.set({ pending: { kind, anchor, status, quoteText }, view: 'page' })
    this.openPanel(true)
  }

  async saveCoverage(anchor: Anchor, status: CoverageStatus, body?: string) {
    const { pkg, hello, teachSections, meetingDate, build } = this.state
    if (!pkg || !hello) return
    this.set({ busy: true, error: null })
    try {
      const sections = await Promise.all(teachSections.map(async (section_id) => ({ section_id, meeting_id: (await api.ensureMeeting(section_id, meetingDate)).id })))
      const row = await api.createMark({ kind: 'coverage', package_id: pkg.id, page: hello.page, anchor, body: body || null, data: { status }, build_id: build?.id || null }, sections)
      this.set({ marks: [...this.state.marks, row], pending: null })
      this.pushMarks()
      const labels = this.state.sections.filter((s) => teachSections.includes(s.id)).map((s) => s.label).join(', ')
      this.send({ type: 'yrS4:toast', text: `${status === 'covered' ? 'Covered' : status === 'assigned' ? 'Read on your own' : 'Skipped'} · ${labels} · ${meetingDate}`, undo: row.id })
      void this.loadPageCoverage()
    } catch (e) {
      this.fail(e)
    } finally {
      this.set({ busy: false })
    }
  }

  /** Save a comment (to the Teach sections) or a private note. */
  async saveText(p: Pending, body: string, data: Record<string, unknown>) {
    const { pkg, hello, teachSections, meetingDate, build } = this.state
    if (!pkg || !hello) return
    this.set({ busy: true, error: null })
    try {
      if (p.editing) {
        await api.updateMark(p.editing.id, { body, data: { ...p.editing.data, ...data } })
        this.set({ marks: this.state.marks.map((m) => (m.id === p.editing!.id ? { ...m, body, data: { ...m.data, ...data } } : m)), pending: null })
      } else {
        let sections: Array<{ section_id: string; meeting_id?: string | null }> = []
        if (p.kind === 'comment') sections = await Promise.all(teachSections.map(async (section_id) => ({ section_id, meeting_id: (await api.ensureMeeting(section_id, meetingDate)).id })))
        if (p.kind === 'message' || p.kind === 'reaction') {
          const mine = this.state.sections.filter((x) => this.state.enrolledIds.includes(x.id))
          const target = this.state.section && mine.some((x) => x.id === this.state.section!.id) ? [this.state.section] : mine
          if (!target.length) throw new api.ApiError(p.kind === 'reaction' ? 'Join your section first (Settings → join code), so your instructor sees the count.' : 'Join your section first (Settings → join code from your instructor), so the message reaches its staff.')
          sections = target.map((x) => ({ section_id: x.id }))
        }
        const row = await api.createMark({ kind: p.kind, package_id: pkg.id, page: hello.page, anchor: p.anchor, body, data, build_id: build?.id || null }, sections)
        this.set({ marks: [...this.state.marks, row], pending: null })
        if (p.kind === 'author_note' && !this.state.showNotes) this.setShowNotes(true)
      }
      this.pushMarks()
      this.toast(p.kind === 'comment' ? 'Comment saved' : p.kind === 'message' ? 'Sent to your instructor' : p.kind === 'reaction' ? `${data.emoji} noted (press again to undo)` : p.kind === 'student_note' && data.highlight ? 'Highlighted' : 'Note saved')
    } catch (e) {
      this.fail(e)
    } finally {
      this.set({ busy: false })
    }
  }

  edit(m: MarkRow) {
    if (!m.anchor) return
    this.set({ pending: { kind: m.kind, anchor: m.anchor, quoteText: m.anchor.quote?.exact, editing: m }, view: 'page' })
  }
  cancelPending() {
    this.set({ pending: null })
  }

  async changeStatus(m: MarkRow, status: CoverageStatus) {
    try {
      await api.setCoverageStatus(m.id, m.data, status)
      this.set({ marks: this.state.marks.map((x) => (x.id === m.id ? { ...x, data: { ...x.data, status } } : x)) })
      this.pushMarks()
    } catch (e) {
      this.fail(e)
    }
  }

  async setStatus(m: MarkRow, status: string) {
    try {
      await api.updateMark(m.id, { status })
      this.set({ marks: this.state.marks.map((x) => (x.id === m.id ? { ...x, status } : x)) })
      this.pushMarks()
    } catch (e) {
      this.fail(e)
    }
  }

  async remove(id: string) {
    const m = this.state.marks.find((x) => x.id === id)
    if (!m) return
    try {
      await api.deleteMark(id)
      this.set({ marks: this.state.marks.filter((x) => x.id !== id), focusMark: null })
      this.pushMarks()
      this.toast('Deleted')
    } catch (e) {
      this.fail(e)
    }
  }

  async markWholePage(status: CoverageStatus) {
    const { pkg, hello } = this.state
    if (!pkg || !hello) return
    const anchor: Anchor = { package: pkg.slug, page: hello.page, scope: 'page', section: { id: '', headings: [hello.title] }, build: this.state.build?.id || 'local' }
    await this.saveCoverage(anchor, status)
  }
}

export const store = new Store()
